/*
 小蓝零工 / Job-Daily — 开源干净基础库（唯一初始化脚本）
 来源：job-daily.sql 清洗 + 代码依赖表/菜单/定时任务补充
 注意：
 1) 不含真实密钥、手机号、订单、提现、简历等隐私/业务数据
 2) 默认后台账号：admin / 123456（上线后立即修改）
 3) 新环境：建库后导入本文件即可
*/

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;


-- ----------------------------
-- Table structure for base_config
-- ----------------------------
DROP TABLE IF EXISTS `base_config`;
CREATE TABLE `base_config` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `config_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '名称',
  `config_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '属性编码',
  `config_value` text COMMENT '属性值',
  `config_flag` int(11) DEFAULT NULL COMMENT '是否是系统参数：1-是，0-否',
  `group_code` varchar(255) DEFAULT NULL COMMENT '所属分类的编码，来自于“常量的分类”字典',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` varchar(3) DEFAULT '1' COMMENT '是否启用',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='参数设置';

-- ----------------------------
-- Records of base_config
-- ----------------------------
-- ----------------------------
-- Table structure for cms_about_us
-- ----------------------------
DROP TABLE IF EXISTS `cms_about_us`;
CREATE TABLE `cms_about_us` (
  `id` varchar(50) NOT NULL COMMENT '关于我们id',
