-- ----------------------------
-- Table structure for cms_notice
-- ----------------------------
DROP TABLE IF EXISTS `cms_notice`;
CREATE TABLE `cms_notice` (
  `id` varchar(50) NOT NULL COMMENT '主键ID',
  `if_public` tinyint(1) DEFAULT '1' COMMENT '是否公共通知',
  `role_code` varchar(50) DEFAULT NULL COMMENT '面向角色：company-招聘端，member-求职端',
  `user_id` varchar(50) DEFAULT NULL COMMENT '用户ID',
  `order_id` varchar(50) DEFAULT NULL COMMENT '订单ID',
  `data_id` varchar(50) DEFAULT NULL COMMENT '关联数据ID，自定义',
  `title` varchar(200) DEFAULT NULL COMMENT '通知标题',
  `type` int(10) DEFAULT '1' COMMENT '通知类型：0-系统通知，1-任务动态，2-平台私信',
  `plat` varchar(20) DEFAULT '1,2' COMMENT '平台：0-全部，1-微信，2-抖音',
  `banner` varchar(1024) DEFAULT NULL COMMENT '轮播大图',
  `avatar` varchar(1024) DEFAULT NULL COMMENT '封面图标',
  `version` varchar(10) DEFAULT NULL COMMENT '版本信息',
  `view_count` int(10) DEFAULT NULL COMMENT '阅读数量',
  `excerpt` varchar(200) DEFAULT NULL COMMENT '摘要',
  `content` text COMMENT '内容',
  `set_top` tinyint(1) DEFAULT '0' COMMENT '是否置顶',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(3) DEFAULT '1' COMMENT '启用状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(10) DEFAULT NULL COMMENT 'tenantId',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='通知内容';

