-- ----------------------------
-- Table structure for integral_goods
-- ----------------------------
DROP TABLE IF EXISTS `integral_goods`;
CREATE TABLE `integral_goods` (
  `id` varchar(50) NOT NULL COMMENT '主键ID',
  `code` varchar(50) DEFAULT NULL COMMENT '商品编号',
  `name` varchar(200) DEFAULT NULL COMMENT '商品名称',
  `image` varchar(500) DEFAULT NULL COMMENT '道具图片',
  `effect` varchar(200) DEFAULT NULL COMMENT '功效',
  `integral` decimal(11,2) DEFAULT NULL COMMENT '积分',
  `period` int(11) DEFAULT NULL COMMENT '时效性：0表示无限期，-1表示单次有效，其他表示小时数',
  `role_code` varchar(50) DEFAULT NULL COMMENT '面向角色',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(11) DEFAULT NULL COMMENT '启用状态',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='积分道具';

-- ----------------------------
-- Records of integral_goods
-- ----------------------------

-- ----------------------------
-- Table structure for integral_goods_effect
-- ----------------------------
DROP TABLE IF EXISTS `integral_goods_effect`;
CREATE TABLE `integral_goods_effect` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `user_id` varchar(50) DEFAULT NULL COMMENT '会员ID',
  `data_id` varchar(50) DEFAULT NULL COMMENT '关联数据ID，如岗位ID或者简历ID',
  `goods_id` varchar(50) DEFAULT NULL COMMENT '道具商品ID',
  `goods_code` varchar(50) DEFAULT NULL COMMENT '道具编码',
  `period` int(11) DEFAULT NULL COMMENT '时效（小时）',
  `start_time` datetime DEFAULT NULL COMMENT '生效时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `status` int(11) DEFAULT NULL COMMENT '启用状态：如果过期了则自动停用',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='道具时效';

-- ----------------------------
-- Records of integral_goods_effect (cleared for open-source)
-- ----------------------------

-- ----------------------------
-- Table structure for integral_goods_order
-- ----------------------------
DROP TABLE IF EXISTS `integral_goods_order`;
CREATE TABLE `integral_goods_order` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `order_sn` varchar(50) DEFAULT NULL COMMENT '订单编码',
  `user_id` varchar(50) DEFAULT NULL COMMENT '会员ID',
  `goods_id` varchar(50) DEFAULT NULL COMMENT '商品ID',
  `original_price` decimal(11,2) DEFAULT NULL COMMENT '原单价',
  `price` decimal(11,2) DEFAULT NULL COMMENT '现单价',
  `number` int(11) DEFAULT NULL COMMENT '购买数量',
  `original_amount` decimal(11,2) DEFAULT NULL COMMENT '订单原价',
  `discount_amount` decimal(11,2) DEFAULT NULL COMMENT '订单优惠价',
  `amount` decimal(11,2) DEFAULT NULL COMMENT '订单总额',
  `order_status` varchar(5) DEFAULT NULL COMMENT '订单状态',
  `pay_type` varchar(10) DEFAULT NULL COMMENT '支付方式',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` date DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` date DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='积分道具订单';

