DROP TABLE IF EXISTS `job_post`;
CREATE TABLE `job_post` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `user_id` varchar(50) DEFAULT NULL COMMENT '用户ID',
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `settlement_type` int(11) DEFAULT NULL COMMENT '结算方式，兼职，日结、周结、月结、完工结',
  `post_source` tinyint(1) DEFAULT '0' COMMENT '只为来源：0-自己发布，1-平台发布',
  `type_ids` varchar(500) DEFAULT NULL COMMENT '工种id',
  `type_codes` varchar(500) DEFAULT NULL COMMENT '工种编码',
  `type_names` varchar(500) DEFAULT NULL COMMENT '工种名称',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `close_time` datetime DEFAULT NULL COMMENT '招工截止',
  `sex_require` varchar(30) DEFAULT NULL COMMENT '性别要求',
  `age_require` varchar(50) DEFAULT NULL COMMENT '年龄要求',
  `recruits_number` int(11) DEFAULT NULL COMMENT '招聘人数',
  `address_name` varchar(255) DEFAULT NULL COMMENT '地址名称',
  `address_house` varchar(255) DEFAULT NULL COMMENT '门牌号',
  `address` varchar(200) DEFAULT NULL COMMENT '工作地点',
  `longitude` varchar(30) DEFAULT NULL COMMENT '地点经度',
  `latitude` varchar(30) DEFAULT NULL COMMENT '地点纬度',
  `phone` varchar(11) DEFAULT NULL COMMENT '联系电话',
  `name` varchar(20) DEFAULT NULL COMMENT '联系人姓名',
  `descr` text COMMENT '职位描述',
  `pricing_mode` varchar(30) DEFAULT NULL COMMENT '计价方式：计时、计件',
  `salary` varchar(30) DEFAULT NULL COMMENT '薪资范围',
  `salary_unit` varchar(255) DEFAULT NULL COMMENT '薪资单位，兼职，元/时，元/天，元/周，元/月',
  `job_requires` varchar(500) DEFAULT NULL COMMENT '招工要求',
  `video_url` varchar(1000) DEFAULT NULL COMMENT '工作视频',
  `img_url` varchar(1000) DEFAULT NULL COMMENT '工作图片',
  `if_call` int(11) DEFAULT NULL COMMENT '是否需要电话沟通',
  `browse_number` int(11) DEFAULT '0' COMMENT '浏览数量',
  `if_topping` int(11) DEFAULT NULL COMMENT '是否置顶',
  `if_bold` int(11) DEFAULT NULL COMMENT '是否加粗',
  `remark` varchar(255) DEFAULT NULL COMMENT '内容描述',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `post_status` int(11) DEFAULT NULL COMMENT '招工状态：1-待审核，2-招工中，3-发布失败，4-已停招，5-已取消，6-已招满',
  `city` varchar(50) DEFAULT NULL COMMENT '县级城市名称',
  `city_code` varchar(50) DEFAULT NULL COMMENT '县级城市编码',
  `p_city` varchar(50) DEFAULT NULL COMMENT '市级城市名称',
  `p_city_code` varchar(50) DEFAULT NULL COMMENT '市级城市编码',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='招工信息';

