  `p_city` varchar(50) DEFAULT NULL COMMENT '市级城市名称',
  `p_city_code` varchar(50) DEFAULT NULL COMMENT '市级城市编码',
  `work_type` varchar(50) DEFAULT NULL COMMENT '工作类型：全职、兼职等',
  `expect_salary` varchar(100) DEFAULT NULL COMMENT '期望薪资',
  `salary_unit` varchar(50) DEFAULT NULL COMMENT '薪资单位：元/日、元/月、元/件等',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(11) DEFAULT NULL COMMENT '启用状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='求职意向';

-- ----------------------------
-- Records of job_resume_intention (cleared for open-source)
-- ----------------------------

-- ----------------------------
-- Table structure for job_types
-- ----------------------------
DROP TABLE IF EXISTS `job_types`;
CREATE TABLE `job_types` (
  `id` varchar(50) NOT NULL COMMENT 'id',
  `name` varchar(255) DEFAULT NULL COMMENT '工种名称',
  `if_hot` varchar(3) DEFAULT NULL COMMENT '是否热门',
  `if_public` tinyint(1) DEFAULT '1' COMMENT '是否公共工种',
  `user_id` varchar(50) DEFAULT NULL COMMENT '用户ID,针对私有类型',
  `type_code` varchar(50) DEFAULT NULL COMMENT '工种编码',
  `level` tinyint(1) DEFAULT NULL COMMENT '层级',
  `remark` varchar(255) DEFAULT NULL COMMENT '描述',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(11) DEFAULT NULL COMMENT '启用状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  `pid` varchar(32) DEFAULT NULL COMMENT '父级节点',
  `has_child` varchar(3) DEFAULT NULL COMMENT '是否有子节点',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='工种信息';

-- ----------------------------
-- Records of job_types
-- ----------------------------

-- ----------------------------
-- Table structure for onl_auth_data
-- ----------------------------
DROP TABLE IF EXISTS `onl_auth_data`;
CREATE TABLE `onl_auth_data` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `cgform_id` varchar(32) DEFAULT NULL COMMENT 'online表ID',
  `rule_name` varchar(50) DEFAULT NULL COMMENT '规则名',
  `rule_column` varchar(50) DEFAULT NULL COMMENT '规则列',
  `rule_operator` varchar(50) DEFAULT NULL COMMENT '规则条件 大于小于like',
  `rule_value` varchar(255) DEFAULT NULL COMMENT '规则值',
  `status` int(11) DEFAULT NULL COMMENT '1有效 0无效',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of onl_auth_data
