-- ----------------------------
-- Table structure for ums_account
-- ----------------------------
DROP TABLE IF EXISTS `ums_account`;
CREATE TABLE `ums_account` (
  `id` varchar(50) NOT NULL COMMENT '账户ID',
  `user_id` varchar(50) DEFAULT NULL COMMENT '会员ID',
  `balance_frozen` decimal(12,2) DEFAULT '0.00' COMMENT '冻结余额',
  `balance_withdraw` decimal(12,2) DEFAULT '0.00' COMMENT '可提余额',
  `balance` decimal(12,2) DEFAULT '0.00' COMMENT '可用余额',
  `total_recharge` decimal(12,2) DEFAULT '0.00' COMMENT '充值总额',
  `total_withdraw` decimal(12,2) DEFAULT '0.00' COMMENT '提现总额',
  `total_consume` decimal(12,2) DEFAULT '0.00' COMMENT '消费总额',
  `integral` int(11) DEFAULT '0' COMMENT '会员积分',
  `total_integral` int(11) DEFAULT '0' COMMENT '累计积分',
  `create_time` date DEFAULT NULL COMMENT '添加时间',
  `update_time` date DEFAULT NULL COMMENT '修改时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`),
  KEY `member_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='会员账户';

