-- ----------------------------
DROP TABLE IF EXISTS `ums_vip`;
CREATE TABLE `ums_vip` (
  `id` varchar(50) NOT NULL COMMENT 'VIP id',
  `role_code` varchar(50) DEFAULT NULL COMMENT '角色编码',
  `vip_type` varchar(10) DEFAULT NULL COMMENT 'VIP类型',
  `name` varchar(20) DEFAULT NULL COMMENT '名称',
  `price` decimal(11,2) DEFAULT NULL COMMENT 'VIP价格信息',
  `unit_price` decimal(11,2) DEFAULT '0.00' COMMENT '单价',
  `integral` int(11) DEFAULT NULL COMMENT '所需积分',
  `days` int(11) DEFAULT NULL COMMENT '日期长度',
  `rate` varchar(10) DEFAULT NULL COMMENT '折扣率',
  `equity` varchar(500) DEFAULT NULL COMMENT '会员权益',
  `remark` varchar(255) DEFAULT NULL COMMENT '内容描述',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(11) DEFAULT NULL COMMENT '启用状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='VIP价格信息表';

-- ----------------------------
-- Records of ums_vip
-- ----------------------------

-- ----------------------------
-- Table structure for ums_vip_orders
-- ----------------------------
DROP TABLE IF EXISTS `ums_vip_orders`;
CREATE TABLE `ums_vip_orders` (
  `id` varchar(50) NOT NULL COMMENT '订单ID',
  `orders_sn` varchar(100) DEFAULT NULL COMMENT '订单编号',
  `member_id` varchar(50) DEFAULT NULL COMMENT '购买会员id',
  `vip_id` varchar(50) DEFAULT NULL COMMENT 'VIP id',
  `vip_name` varchar(20) DEFAULT NULL COMMENT 'VIP名称',
  `total_amount` decimal(12,2) DEFAULT NULL COMMENT '订单原价',
  `pay_amount` decimal(12,2) DEFAULT NULL COMMENT '订单实付',
  `pay_type` varchar(20) DEFAULT NULL COMMENT '支付方式',
  `orders_status` int(11) DEFAULT NULL COMMENT '订单状态',
  `note` varchar(200) DEFAULT NULL COMMENT '订单备注',
  `source_type` int(11) DEFAULT NULL COMMENT '订单来源',
  `source_version` varchar(30) DEFAULT NULL COMMENT '软件版本',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='VIP购买记录表';

-- ----------------------------
-- Records of ums_vip_orders (cleared for open-source)
-- ----------------------------

-- ----------------------------
-- Table structure for ums_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `ums_withdraw`;
CREATE TABLE `ums_withdraw` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `out_bill_no` varchar(50) DEFAULT NULL COMMENT '商户单号',
  `user_id` varchar(50) DEFAULT NULL COMMENT '会员ID',
  `money` decimal(10,2) DEFAULT NULL COMMENT '提现金额',
  `last_balance` decimal(10,2) DEFAULT NULL COMMENT '提现前余额',
  `balance` decimal(10,2) DEFAULT NULL COMMENT '提现后余额',
  `withdraw_status` int(11) DEFAULT NULL COMMENT '提现状态:0-待审核，1-审核通过，2-审核失败',
  `reason` varchar(200) DEFAULT NULL COMMENT '提现失败原因',
  `account_type` int(11) DEFAULT NULL COMMENT '账户类型：0-支付宝，1-微信，2-银联',
  `withdraw_account` varchar(50) DEFAULT NULL COMMENT '提现账号（账号信息、银行卡号等）',
  `withdraw_name` varchar(50) DEFAULT NULL COMMENT '关联名称（支付宝-实名，微信-昵称，银联-持卡人）',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '银行名称',
  `bank_branch_name` varchar(200) DEFAULT NULL COMMENT '支行信息',
  `verify_method` tinyint(1) DEFAULT '0' COMMENT '审核方式：0-人工，1-自动',
  `transfer_status` varchar(50) DEFAULT NULL COMMENT '转账状态：ACCEPTED-已受理，PROCESSING-转账锁定资金中，WAIT_USER_CONFIRM-待收款用户确认，TRANSFERING-转账中，SUCCESS-转账成功，FAIL- 转账失败，CANCELING-转账撤销中，CANCELLED-转账撤销完成',
  `package_info` text COMMENT '跳转领取页面的package信息',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  `abnormal_notes` varchar(500) DEFAULT NULL COMMENT '异常单处理说明',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_withdraw_out_bill` (`out_bill_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='提现记录';

-- ----------------------------
-- Records of ums_withdraw (cleared for open-source)
-- ----------------------------

