-- 余额充值单
DROP TABLE IF EXISTS `ums_balance_recharge`;
CREATE TABLE `ums_balance_recharge` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) DEFAULT NULL COMMENT '用户ID',
  `order_sn` varchar(64) DEFAULT NULL COMMENT '商户订单号',
  `money` decimal(14,2) DEFAULT NULL COMMENT '充值金额(元)',
  `pay_type` varchar(20) DEFAULT NULL COMMENT '支付方式',
  `recharge_status` varchar(10) DEFAULT '0' COMMENT '0未支付1成功2失败',
  `create_by` varchar(50) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(50) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  `sys_org_code` varchar(64) DEFAULT NULL,
  `tenant_id` int(11) DEFAULT NULL,
  `del_flag` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_balance_recharge_sn` (`order_sn`),
  KEY `idx_balance_recharge_user` (`user_id`),
  KEY `idx_balance_recharge_status` (`recharge_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='余额充值单';

-- 用户阈值（实体 UmsParamLimit，无业务流水）
DROP TABLE IF EXISTS `ums_param_limit`;
CREATE TABLE `ums_param_limit` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `user_id` varchar(36) DEFAULT NULL COMMENT '用户ID',
  `apply_num` int(11) DEFAULT NULL COMMENT '简历投递次数',
  `used_apply_num` int(11) DEFAULT NULL COMMENT '已投递次数',
  `status` int(11) DEFAULT 1 COMMENT '启用状态',
  `create_by` varchar(50) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(50) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `sys_org_code` varchar(64) DEFAULT NULL,
  `tenant_id` int(11) DEFAULT NULL,
  `del_flag` int(11) DEFAULT 0 COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`),
  KEY `idx_param_limit_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户阈值';

-- 业务消息模板
DROP TABLE IF EXISTS `biz_msg_template`;
CREATE TABLE `biz_msg_template` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `template_code` varchar(64) NOT NULL COMMENT '模板编码',
  `channel` varchar(16) NOT NULL COMMENT '通道 site/wx',
  `wx_template_id` varchar(128) DEFAULT NULL COMMENT '微信订阅模板ID',
  `title` varchar(200) DEFAULT NULL COMMENT '标题模板',
  `content` varchar(1000) DEFAULT NULL COMMENT '内容模板，支持{var}',
  `field_mapping` varchar(1000) DEFAULT NULL COMMENT '字段映射JSON',
  `status` varchar(3) DEFAULT '1' COMMENT '1启用0停用',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` varchar(32) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(32) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` int(11) DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='业务消息模板';

